// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dlagtm, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 22', function test( t ) {
	t.strictEqual( dlagtm.length, 22, 'returns expected value' );
	t.end();
});

tape( 'the function throws an error if provided an invalid first argument', function test( t ) {
	var values;
	var data;
	var i;

	data = NO_TRANS_A1_B0_RM;

	values = [
		'foo',
		'bar',
		'beep',
		'boop'
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			dlagtm( value, data.N, data.NRHS, data.alpha, new Float64Array( data.DL ), data.strideDL, data.offsetDL, new Float64Array( data.D ), data.strideD, data.offsetD, new Float64Array( data.DU ), data.strideDU, data.offsetDU, new Float64Array( data.X ), data.strideX1, data.strideX2, data.offsetX, data.beta, new Float64Array( data.B ), data.strideB1, data.strideB2, data.offsetB );
		};
	}
});

