tape( 'the function returns B unchanged when N is 0', function test( t ) {
	var expected;
	var out;
	var B;

	B = new Float64Array( [ 1.0, 2.0 ] );
	expected = new Float64Array( [ 1.0, 2.0 ] );

	out = dlagtm( 'no-transpose', 0, 2, 1.0, new Float64Array( [] ), 1, 0, new Float64Array( [] ), 1, 0, new Float64Array( [] ), 1, 0, new Float64Array( [] ), 2, 1, 0, 0.0, B, 2, 1, 0 );
	t.strictEqual( out, B, 'returns expected value' );
	t.deepEqual( out, expected, 'returns expected value' );
	t.end();
});

tape( 'the function handles NRHS = 0', function test( t ) {
	var expected;
	var out;
	var B;

	// When NRHS is 0, neither beta scaling nor A*X loops execute (inner loop count is 0):
	B = new Float64Array( [ 1.0, 2.0, 3.0 ] );
	expected = new Float64Array( [ 1.0, 2.0, 3.0 ] );

	out = dlagtm( 'no-transpose', 3, 0, 1.0, new Float64Array( [ 1.0, 1.0 ] ), 1, 0, new Float64Array( [ 2.0, 3.0, 4.0 ] ), 1, 0, new Float64Array( [ 1.0, 1.0 ] ), 1, 0, new Float64Array( [] ), 1, 1, 0, 0.0, B, 1, 1, 0 );
	t.strictEqual( out, B, 'returns expected value' );
	t.deepEqual( out, expected, 'returns expected value' );
	t.end();
});

