tape( 'the function only modifies indexed elements of B (row-major)', function test( t ) {
	var expected;
	var data;
	var out;
	var B;
	var i;
	var j;

	data = NO_TRANS_A1_BN1_RM;

	// Provide a matrix `B` having a stride for the first dimension which is larger than `NRHS`, such that interstitial elements should remain unchanged...
	B = new Float64Array( data.N*(data.NRHS+2) );
	expected = new Float64Array( B.length );
	for ( i = 0; i < B.length; i++ ) {
		B[ i ] = 999.0;
		expected[ i ] = 999.0;
	}
	for ( i = 0; i < data.N; i++ ) {
		for ( j = 0; j < data.NRHS; j++ ) {
			B[ (i*(data.NRHS+2))+j ] = data.B[ (i*data.NRHS)+j ];
			expected[ (i*(data.NRHS+2))+j ] = data.B_out[ (i*data.NRHS)+j ];
		}
	}
	out = dlagtm( data.trans, data.N, data.NRHS, data.alpha, new Float64Array( data.DL ), data.strideDL, data.offsetDL, new Float64Array( data.D ), data.strideD, data.offsetD, new Float64Array( data.DU ), data.strideDU, data.offsetDU, new Float64Array( data.X ), data.strideX1, data.strideX2, data.offsetX, data.beta, B, data.NRHS+2, 1, 0 );
	t.strictEqual( out, B, 'returns expected value' );
	t.deepEqual( out, expected, 'returns expected value' );
	t.end();
});

